def maximizeLotteryId(lotteryID: str, winnerID: str, k: int) -> int:
    a, b = lotteryID, winnerID  # 题目只涉及小写字母
    n, m = len(a), len(b)

    def cost(x: str, y: str) -> int:
        d = abs(ord(x) - ord(y))
        return min(d, 26 - d)  # 字母表是环，可以往前也可以往后转

    # prev[j][c]：lotteryID 前 i-1 个、winnerID 前 j 个、总花费不超过 c 时的最长 LCS
    prev = [[0] * (k + 1) for _ in range(m + 1)]
    for i in range(1, n + 1):
        cur = [[0] * (k + 1) for _ in range(m + 1)]
        for j in range(1, m + 1):
            d = cost(a[i - 1], b[j - 1])
            up, left, diag, row = prev[j], cur[j - 1], prev[j - 1], cur[j]
            for c in range(k + 1):
                v = up[c] if up[c] > left[c] else left[c]
                if d <= c and diag[c - d] + 1 > v:
                    v = diag[c - d] + 1
                row[c] = v
        prev = cur
    return prev[m][k]
